with valid as (select *, coalesce(location, 'N/A') as location_filled, coalesce(location, 'N/A') as location_filled_2 from departments where location is not null and dept_name is distinct from 'Finance') select case when budget >= 3586000 then 'LARGE' else 'SMALL' end as budget_tier, round(sum(budget) / nullif(count(case when location = 'Berlin' then 1 end), 0), 2) as budget_per_berlin, count(case when dept_name = 'Legal' then 1 end) as legal_count, sort_array(collect_set(location)) as location_list, percentile_approx(budget, 0.95) as budget_p95, sort_array(collect_set(location)) as location_list_2, sort_array(collect_set(location)) as location_list_3 from valid group by 1 order by budget_tier desc nulls last
